-- Separate monthly SMG plans; existing daily staffing plans are unchanged.
CREATE TABLE gdlr_hierarchy_nodes (
 id TEXT PRIMARY KEY,
 parent_id TEXT REFERENCES gdlr_hierarchy_nodes(id),
 label TEXT NOT NULL,
 name_key TEXT NOT NULL UNIQUE,
 is_group BOOLEAN NOT NULL,
 sort_order INTEGER NOT NULL,
 category_id BIGINT UNIQUE REFERENCES gdlr_categories(id) ON DELETE SET NULL
);
CREATE TABLE smg_plan_versions (
 id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
 scope TEXT NOT NULL,
 period DATE NOT NULL CHECK(EXTRACT(DAY FROM period)=1),
 version INTEGER NOT NULL CHECK(version>0),
 previous_id UUID REFERENCES smg_plan_versions(id),
 source JSONB NOT NULL,
 created_by BIGINT NOT NULL REFERENCES users(id),
 created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
 request_key UUID NOT NULL,
 UNIQUE(scope,period,version),
 UNIQUE(created_by,request_key)
);
CREATE TABLE smg_plan_values (
 version_id UUID NOT NULL REFERENCES smg_plan_versions(id),
 node_id TEXT NOT NULL REFERENCES gdlr_hierarchy_nodes(id),
 value NUMERIC NOT NULL CHECK(value>=0 AND value<=100000000),
 PRIMARY KEY(version_id,node_id)
);
CREATE INDEX smg_plan_latest ON smg_plan_versions(scope,period,version DESC);
GRANT SELECT,INSERT ON smg_plan_versions,smg_plan_values TO workforce_app;
GRANT SELECT,UPDATE ON gdlr_hierarchy_nodes TO workforce_app;
